class Solution {
public:
    int getSum(vector<int>& nums) {
        const long long MOD = 1000000007LL;
        int v = *max_element(nums.begin(), nums.end()) + 2;
        vector<long long> upC(v + 1), downC(v + 1), upS(v + 1), downS(v + 1);
        long long ans = 0;
        for (int x : nums) {
            long long c1 = upC[x - 1], c2 = downC[x + 1];
            long long s1 = (upS[x - 1] + c1 * x) % MOD;
            long long s2 = (downS[x + 1] + c2 * x) % MOD;
            ans = (ans + x + s1 + s2) % MOD;
            upC[x] = (upC[x] + c1 + 1) % MOD;
            downC[x] = (downC[x] + c2 + 1) % MOD;
            upS[x] = (upS[x] + s1 + x) % MOD;
            downS[x] = (downS[x] + s2 + x) % MOD;
        }
        return (int)ans;
    }
};
